function Badge({ children, color }) {
  return (
    <span style={{
      background:color+"22", color, border:`1px solid ${color}44`,
      borderRadius:20, padding:"2px 10px", fontSize:14, fontWeight:700, letterSpacing:0.5,
    }}>{children}</span>
  );
}

function Barra({ valor, max, cor=C.accent, h=6 }) {
  return (
    <div style={{ height:h, background:C.border, borderRadius:10, overflow:"hidden" }}>
      <div style={{
        height:"100%", borderRadius:10, transition:"width 1s ease",
        width:`${Math.min((valor/max)*100,100)}%`,
        background:`linear-gradient(90deg,${cor},${cor}AA)`,
        boxShadow:`0 0 8px ${cor}80`,
      }}/>
    </div>
  );
}

function EscalaInput({ value, onChange }) {
  const cores  = ["",C.danger,"#F97316",C.warning,C.success,"#00D4AA"];
  const labels = ["","Muito ruim","Ruim","Regular","Bom","Excelente"];
  return (
    <div>
      <div style={{ display:"flex", gap:10, marginBottom:8 }}>
        {[1,2,3,4,5].map(n => (
          <button key={n} onClick={()=>onChange(n)} style={{
            width:52, height:52, borderRadius:14, fontSize:18, fontWeight:800, cursor:"pointer",
            border:`2px solid ${value===n?cores[n]:C.border}`,
            background:value===n?cores[n]+"25":C.card,
            color:value===n?cores[n]:C.muted,
            transform:value===n?"scale(1.1)":"scale(1)", transition:"all 0.15s",
          }}>{n}</button>
        ))}
      </div>
      {value && <span style={{ color:cores[value], fontSize:14, fontWeight:700 }}>{labels[value]}</span>}
    </div>
  );
}

function BinariaInput({ value, onChange }) {
  return (
    <div style={{ display:"flex", gap:12 }}>
      {[["Sim",C.success,"👍"],["Não",C.danger,"👎"]].map(([op,cor,em])=>(
        <button key={op} onClick={()=>onChange(op)} style={{
          minHeight:48, padding:"12px 32px", borderRadius:12, cursor:"pointer", fontWeight:600, fontSize:16, boxSizing:"border-box",
          border:`2px solid ${value===op?cor:C.border}`,
          background:value===op?cor+"22":C.card, color:value===op?cor:C.muted,
          transform:value===op?"scale(1.05)":"scale(1)", transition:"all 0.15s",
        }}>{em} {op}</button>
      ))}
    </div>
  );
}

