// ── TAB: KPIs DIRETOR ────────────────────────────────────────────────────────
function KPIsTab({ missionarios, dadosFinanceiros, kpisApi }) {
  const fileRef = useRef();
  const [fins, setFins]       = useState(dadosFinanceiros);
  const [csvErro, setCsvErro] = useState("");
  const [csvOk, setCsvOk]     = useState(false);

  // ── Cálculos automáticos do cadastro de missionários
  const total   = missionarios.length;
  const ativos  = missionarios.filter(m => m.status === "ativo").length;
  const inativos= missionarios.filter(m => m.status === "inativo").length;
  const retencao= total > 0 ? ((ativos / total) * 100).toFixed(1) : "—";

  // Novos nos últimos 30 dias (mock: tl===0 → recém cadastrado)
  const novos = missionarios.filter(m => m.tl === 0).length;

  // ── Scores dos Pulsos (mock representativo — virá das avaliações reais)
  const pulsos = {
    lideranca: 4.1,   // KPI 7 — Pulso de Liderança
    rh_participacao: 3.9, // KPI 6 — Pulso Área RH q3
    operacoes_planu: 4.0, // KPI 8 — Pulso Área Operações q2
    evento_satisfacao: 4.3, // KPI 3 — Pulso de Evento
  };

  // ── Inputs manuais (KPIs 4 e 5)
  const [projAlinhados, setProjAlinhados] = useState(82); // %
  const [povosAlcancados, setPovosAlcancados] = useState(7); // projetos ativos

  // ── Parser CSV financeiro
  function handleCSV(e) {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const linhas = ev.target.result.trim().split("\n")
          .map(l => l.split(",").map(c => c.trim().replace(/[^0-9.-]/g, "")));
        const dados = linhas.slice(1).map(([desc, orc, real]) => ({
          desc, orcado: parseFloat(orc)||0, realizado: parseFloat(real)||0
        })).filter(d => d.orcado > 0);
        if (!dados.length) { setCsvErro("Nenhum dado válido encontrado."); return; }
        setFins(dados); setCsvErro(""); setCsvOk(true);
      } catch { setCsvErro("Arquivo inválido. Use CSV: descrição, orçado, realizado"); }
    };
    reader.readAsText(file);
  }

  // ── Cálculos financeiros
  const totalOrc  = fins.reduce((s,d) => s + d.orcado, 0);
  const totalReal = fins.reduce((s,d) => s + d.realizado, 0);
  const desvio    = totalOrc > 0 ? (((totalReal - totalOrc) / totalOrc) * 100).toFixed(1) : null;

  // KPI 9: % aplicado na atividade-fim (linhas marcadas com "missao" na descrição)
  const realMissao = fins.filter(d => d.desc?.toLowerCase().includes("missao") || d.desc?.toLowerCase().includes("missão"))
                         .reduce((s,d) => s + d.realizado, 0);
  const pctAtivFim = totalReal > 0 ? ((realMissao / totalReal) * 100).toFixed(1) : null;

  const fmtBRL = n => n.toLocaleString("pt-BR", { style:"currency", currency:"BRL", maximumFractionDigits:0 });

  // ── Helper de status visual
  function kpiStatus(val, meta, inverso=false) {
    if (val === null || val === undefined) return { cor: C.muted, label: "Sem dado" };
    const ok = inverso ? val <= meta : val >= meta;
    return ok
      ? { cor: C.success, label: "✅ Meta atingida" }
      : { cor: C.danger,  label: "⚠️ Abaixo da meta" };
  }

  const KPIS = [
    // DIMENSÃO 1 — Resultados de Impacto
    {
      dim: "🎯 Resultados de Impacto da Missão (45%)",
      itens: [
        { num:1, nome:"Taxa de retenção de missionários",     valor:`${retencao}%`,  meta:"≥ 90%",  status: kpiStatus(parseFloat(retencao), 90), fonte:"Cadastro de missionários" },
        { num:2, nome:"Novos missionários recrutados (30d)",  valor:novos,           meta:"≥ 2/trim",status: kpiStatus(novos, 2),                fonte:"Cadastro de missionários" },
        { num:3, nome:"Satisfação com encontros estratégicos",valor:`${pulsos.evento_satisfacao}/5`, meta:"≥ 4.0", status: kpiStatus(pulsos.evento_satisfacao, 4.0), fonte:"Pulso de Evento" },
        { num:4, nome:"% projetos alinhados à missão",        valor:`${projAlinhados}%`, meta:"≥ 80%", status: kpiStatus(projAlinhados, 80), fonte:"Input manual", editavel:true, val:projAlinhados, set:setProjAlinhados },
        { num:5, nome:"Projetos ativos — povos não alcançados",valor:povosAlcancados, meta:"≥ 5",    status: kpiStatus(povosAlcancados, 5),    fonte:"Input manual", editavel:true, val:povosAlcancados, set:setPovosAlcancados },
      ]
    },
    // DIMENSÃO 2 — Capacidade Estratégica
    {
      dim: "🌟 Capacidade Estratégica e Liderança (35%)",
      itens: [
        { num:6, nome:"Participação dos missionários nas equipes", valor:`${pulsos.rh_participacao}/5`, meta:"≥ 4.0", status: kpiStatus(pulsos.rh_participacao, 4.0), fonte:"Pulso de Área — RH" },
        { num:7, nome:"Avaliação do Diretor Executivo",            valor:`${pulsos.lideranca}/5`,       meta:"≥ 4.0", status: kpiStatus(pulsos.lideranca, 4.0),       fonte:"Pulso de Liderança" },
        { num:8, nome:"Adesão ao PLANU",                           valor:`${pulsos.operacoes_planu}/5`, meta:"≥ 4.0", status: kpiStatus(pulsos.operacoes_planu, 4.0), fonte:"Pulso de Área — Operações" },
      ]
    },
    // DIMENSÃO 3 — Eficiência Operacional
    {
      dim: "⚙️ Eficiência Operacional e Governança (20%)",
      itens: [
        { num:9,  nome:"% recursos na atividade-fim",         valor: pctAtivFim ? `${pctAtivFim}%` : "—", meta:"≥ 70%", status: kpiStatus(parseFloat(pctAtivFim), 70), fonte:"Relatório financeiro" },
        { num:10, nome:"Orçamento realizado vs. estimado",     valor: desvio !== null ? `${desvio > 0 ? "+" : ""}${desvio}%` : "—", meta:"≤ ±10%", status: kpiStatus(Math.abs(parseFloat(desvio)), 10, true), fonte:"Relatório financeiro" },
      ]
    },
  ];

  return (
    <div>
      {/* Título */}
      <div style={{ marginBottom:20 }}>
        <h2 style={{ fontSize:22, fontWeight:700, margin:"0 0 4px" }}>📈 Painel de KPIs — Diretor Executivo</h2>
        <p style={{ color:C.muted, fontSize:14, margin:0 }}>Consolidação automática dos 10 indicadores estratégicos</p>
      </div>

      {/* Dados ao vivo da API de pulsos */}
      {kpisApi && (
        <div style={{
          background:C.card, borderRadius:16, padding:20, marginBottom:20,
          border:`1px solid ${C.purple}40`,
        }}>
          <div style={{ fontWeight:700, fontSize:14, marginBottom:10 }}>📡 Pulsos respondidos (dados ao vivo da API)</div>
          <div style={{ display:"flex", gap:12, marginBottom:kpisApi.mediaPorArea?.length?14:0, flexWrap:"wrap" }}>
            <div style={{ background:C.bg, borderRadius:10, padding:"10px 16px", border:`1px solid ${C.border}`, flex:1, minWidth:120, textAlign:"center" }}>
              <div style={{ fontSize:18, fontWeight:800, color:C.purple }}>{kpisApi.totalPulsosRespondidos}</div>
              <div style={{ color:C.muted, fontSize:14 }}>Envios registrados</div>
            </div>
            <div style={{ background:C.bg, borderRadius:10, padding:"10px 16px", border:`1px solid ${C.border}`, flex:1, minWidth:120, textAlign:"center" }}>
              <div style={{ fontSize:18, fontWeight:800, color:C.accent }}>{kpisApi.missionariosAtivos}/{kpisApi.totalMissionarios}</div>
              <div style={{ color:C.muted, fontSize:14 }}>Missionários ativos</div>
            </div>
          </div>
          {kpisApi.mediaPorArea?.length > 0 && (() => {
            // Separa áreas operacionais (com nome/ícone já definidos) de eventos e liderança
            // (que usam o próprio nome do evento/liderado como "área"), em vez de misturar tudo numa lista só.
            const porCiclo = { area: [], evento: [], lideranca: [] };
            for (const linha of kpisApi.mediaPorArea) (porCiclo[linha.ciclo] || porCiclo.area).push(linha);

            return Object.entries(porCiclo).filter(([, linhas]) => linhas.length > 0).map(([cicloId, linhas]) => {
              const ciclo = CICLOS.find(c => c.id === cicloId);
              return (
                <div key={cicloId} style={{ marginBottom:12 }}>
                  <div style={{ color:C.muted, fontSize:14, letterSpacing:1, textTransform:"uppercase", marginBottom:6 }}>
                    {ciclo ? `${ciclo.icon} ${ciclo.label}` : cicloId}
                  </div>
                  <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                    {linhas.map(a => {
                      const areaInfo = cicloId === "area" ? AREAS.find(ar => ar.id === a.area) : null;
                      return (
                        <div key={`${a.ciclo}-${a.area}`} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", fontSize:14 }}>
                          <span>{areaInfo ? `${areaInfo.icon} ${areaInfo.nome}` : a.area} <span style={{ color:C.muted }}>({a.total_respostas} resp.)</span></span>
                          <strong style={{ color:C.purple }}>{a.media}/5</strong>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            });
          })()}
        </div>
      )}

      {/* Upload financeiro */}
      <div style={{
        background:C.card, borderRadius:16, padding:20, marginBottom:20,
        border:`1px solid ${C.border}`,
      }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:10 }}>
          <div>
            <div style={{ fontWeight:700, fontSize:14, marginBottom:3 }}>💰 Relatório Financeiro Mensal</div>
            <div style={{ color:C.muted, fontSize:14 }}>
              CSV com colunas: <code style={{ color:C.accent }}>descrição, orçado, realizado</code>
              {" · "}Marque atividade-fim com "missao" na descrição
            </div>
          </div>
          <div style={{ display:"flex", gap:8, alignItems:"center" }}>
            {csvOk && <Badge color={C.success}>✓ {fins.length} linhas importadas</Badge>}
            {csvErro && <span style={{ color:C.danger, fontSize:14 }}>{csvErro}</span>}
            <Btn small onClick={() => { setCsvOk(false); fileRef.current.click(); }}>
              📥 {fins.length ? "Atualizar" : "Importar CSV"}
            </Btn>
            <input ref={fileRef} type="file" accept=".csv" style={{ display:"none" }} onChange={handleCSV}/>
          </div>
        </div>

        {/* Resumo financeiro quando há dados */}
        {fins.length > 0 && (
          <div style={{ display:"flex", gap:12, marginTop:14, flexWrap:"wrap" }}>
            {[
              ["Orçado", fmtBRL(totalOrc), C.muted],
              ["Realizado", fmtBRL(totalReal), parseFloat(desvio) > 10 ? C.danger : C.success],
              ["Desvio", desvio !== null ? `${desvio > 0 ? "+" : ""}${desvio}%` : "—", Math.abs(parseFloat(desvio)) <= 10 ? C.success : C.danger],
              ["Atividade-fim", pctAtivFim ? `${pctAtivFim}%` : "—", parseFloat(pctAtivFim) >= 70 ? C.success : C.danger],
            ].map(([label, val, cor]) => (
              <div key={label} style={{
                background:C.bg, borderRadius:10, padding:"10px 16px",
                border:`1px solid ${C.border}`, flex:1, minWidth:100, textAlign:"center",
              }}>
                <div style={{ fontSize:16, fontWeight:800, color:cor }}>{val}</div>
                <div style={{ color:C.muted, fontSize:14 }}>{label}</div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* KPIs por dimensão */}
      {KPIS.map(dim => (
        <div key={dim.dim} style={{ marginBottom:16 }}>
          <div style={{ color:C.muted, fontSize:14, letterSpacing:1.5, textTransform:"uppercase", marginBottom:10 }}>
            {dim.dim}
          </div>
          <div style={{ background:C.card, borderRadius:16, border:`1px solid ${C.border}`, overflow:"hidden" }}>
            {dim.itens.map((kpi, i) => (
              <div key={kpi.num} style={{
                padding:"14px 18px", display:"flex", alignItems:"center", gap:14,
                borderBottom: i < dim.itens.length-1 ? `1px solid ${C.border}` : "none",
              }}>
                {/* Número */}
                <div style={{
                  width:28, height:28, borderRadius:"50%", fontSize:14, fontWeight:800,
                  background: kpi.status.cor + "22", color: kpi.status.cor,
                  display:"flex", alignItems:"center", justifyContent:"center",
                  border:`1px solid ${kpi.status.cor}44`, flexShrink:0,
                }}>{kpi.num}</div>

                {/* Nome e fonte */}
                <div style={{ flex:1 }}>
                  <div style={{ fontWeight:600, fontSize:14 }}>{kpi.nome}</div>
                  <div style={{ color:C.muted, fontSize:14, marginTop:2 }}>
                    Fonte: {kpi.fonte} · Meta: {kpi.meta}
                  </div>
                </div>

                {/* Valor — editável nos manuais */}
                {kpi.editavel ? (
                  <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                    <input
                      type="number"
                      value={kpi.val}
                      onChange={e => kpi.set(Number(e.target.value))}
                      style={{
                        width:64, padding:"5px 8px", borderRadius:8, fontSize:14,
                        fontWeight:700, textAlign:"center",
                        background:C.bg, border:`1px solid ${C.border}`, color:C.text,
                        fontFamily:"inherit",
                      }}
                    />
                    <span style={{ color:C.muted, fontSize:14 }}>{kpi.num===4 ? "%" : "proj."}</span>
                  </div>
                ) : (
                  <div style={{ fontWeight:800, fontSize:18, color: kpi.status.cor, minWidth:60, textAlign:"right" }}>
                    {kpi.valor}
                  </div>
                )}

                {/* Status badge */}
                <div style={{ minWidth:130, textAlign:"right" }}>
                  <Badge color={kpi.status.cor}>{kpi.status.label}</Badge>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}

      <div style={{ color:C.muted, fontSize:14, textAlign:"center", marginTop:8 }}>
        KPIs 1, 2 — calculados do cadastro · KPIs 3, 6, 7, 8 — calculados dos Pulsos · KPIs 4, 5 — inserção manual · KPIs 9, 10 — relatório financeiro
      </div>
    </div>
  );
}

// ── AVALIAÇÃO ────────────────────────────────────────────────────────────────
function Avaliacao({ cicloId, perfil, userTL, token, usuario, missionarios, onVoltar, onConcluir }) {
  const ciclo = CICLOS.find(c=>c.id===cicloId);
  const OBJETOS = {
    area:      AREAS,
    evento:    [{ id:"retiro2026", nome:"Retiro Anual 2026", icon:"⛺" },{ id:"encontro_abril", nome:"Encontro Estratégico Abril", icon:"📋" }],
    lideranca: [{ id:"diretor", nome:"Diretor Executivo", icon:"🏆" },{ id:"coord_cuidado", nome:"Coord. Cuidado Missionário", icon:"🤝" }],
  };

  const [etapa, setEtapa] = useState("selecao");
  const [objeto, setObjeto] = useState(null);
  const [respostas, setRespostas] = useState({});
  const [pergAtual, setPergAtual] = useState(0);
  const [showToast, setShowToast] = useState(false);
  const [enviando, setEnviando] = useState(false);
  const [erroEnvio, setErroEnvio] = useState("");

  const perguntas = objeto ? getPerguntasCiclo(cicloId, objeto.id) : [];
  const perg = perguntas[pergAtual];

  function selecionar(o) { setObjeto(o); setPergAtual(0); setRespostas({}); setEtapa("perguntas"); }

  // Perguntas de escala e binárias são obrigatórias para avançar; a aberta continua opcional.
  function respondida(p) {
    if (!p) return false;
    if (p.tipo === "aberta") return true;
    return respostas[p.id] !== undefined && respostas[p.id] !== "";
  }

  async function enviar() {
    setEnviando(true);
    setErroEnvio("");
    let novoTotal = userTL + ciclo.tl;
    try {
      if (token) {
        const missionarioId = missionarios?.find(m =>
          m.email && usuario?.email && m.email.toLowerCase() === usuario.email.toLowerCase()
        )?.id || null;

        const listaRespostas = perguntas
          .filter(p => respostas[p.id] !== undefined && respostas[p.id] !== "")
          .map(p => ({ texto: p.texto, tipo: p.tipo, valor: respostas[p.id] }));

        const resultado = await api.criarPulso(token, {
          missionarioId, ciclo: cicloId, area: objeto.nome, talentos: ciclo.tl, respostas: listaRespostas,
        });
        if (resultado?.missionario?.talentos !== undefined) {
          novoTotal = resultado.missionario.talentos;
        }
      }
    } catch (err) {
      setErroEnvio(err.message || "Não foi possível registrar o pulso na API.");
    } finally {
      setEnviando(false);
      setEtapa("fim"); setShowToast(true); setTimeout(()=>setShowToast(false),3000); onConcluir(novoTotal);
    }
  }

  const headerBack = (
    <div style={{ background:C.surface, borderBottom:`1px solid ${C.border}`, padding:"15px 20px", display:"flex", alignItems:"center", gap:14 }}>
      <button onClick={onVoltar} style={{ background:"none", border:"none", color:C.muted, cursor:"pointer", fontSize:22 }}>←</button>
      <span style={{ fontWeight:700 }}>{ciclo.icon} {ciclo.label}</span>
    </div>
  );

  if (etapa==="selecao") return (
    <div style={{ fontFamily:"'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif", background:C.bg, minHeight:"100vh", color:C.text }}>
      <AppHeader perfil={perfil} userTL={userTL} onHome={onVoltar}/>
      {headerBack}
      <div style={{ maxWidth:560, margin:"0 auto", padding:"32px 20px", boxSizing:"border-box" }}>
        <h2 style={{ fontSize:22, margin:"0 0 4px" }}>O que você vai avaliar?</h2>
        <p style={{ color:C.muted, margin:"0 0 22px", fontSize:14 }}>
          {ciclo.tempo} · Ganhe <strong style={{ color:C.gold }}>+{ciclo.tl} Talentos</strong>
        </p>
        <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
          {OBJETOS[cicloId].map(o=>(
            <div key={o.id} onClick={()=>selecionar(o)} style={{
              background:C.card, borderRadius:16, padding:20, cursor:"pointer",
              border:`1px solid ${C.border}`, display:"flex", alignItems:"center", gap:14,
              transition:"all 0.15s",
            }}
              onMouseEnter={e=>{e.currentTarget.style.borderColor=C.accent;e.currentTarget.style.transform="translateX(4px)";}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.transform="translateX(0)";}}
            >
              <span style={{ fontSize:26 }}>{o.icon}</span>
              <div style={{ flex:1 }}>
                <div style={{ fontWeight:700, fontSize:16 }}>{o.nome}</div>
                <div style={{ color:C.muted, fontSize:14, marginTop:2 }}>
                  {getPerguntasCiclo(cicloId,o.id).length} perguntas · {ciclo.tempo}
                </div>
              </div>
              <Badge color={C.gold}>+{ciclo.tl} TL</Badge>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  if (etapa==="fim") return (
    <div style={{
      fontFamily:"'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif", background:C.bg, minHeight:"100vh", color:C.text,
      display:"flex", alignItems:"center", justifyContent:"center",
      backgroundImage:`radial-gradient(ellipse at 50% 50%,${C.accent}08,transparent 70%)`,
    }}>
      {showToast && <Toast tl={ciclo.tl}/>}
      <div style={{ textAlign:"center", padding:"32px 20px", maxWidth:400, boxSizing:"border-box" }}>
        <div style={{ fontSize:72, marginBottom:16 }}>🎉</div>
        <h2 style={{ fontSize:24, margin:"0 0 8px" }}>Avaliação enviada!</h2>
        <p style={{ color:C.muted, marginBottom:20, lineHeight:1.6 }}>
          Sua voz sobre <strong style={{ color:C.text }}>{objeto?.nome}</strong> foi registrada. Obrigado por fortalecer a SEPAL!
        </p>
        {erroEnvio && (
          <p style={{ color:C.danger, fontSize:14, marginTop:-12, marginBottom:20 }}>
            ⚠ {erroEnvio} (registrado apenas localmente nesta sessão)
          </p>
        )}
        <div style={{
          background:`linear-gradient(135deg,${C.gold}20,${C.accent}20)`,
          border:`1px solid ${C.gold}50`, borderRadius:16, padding:"16px 24px", marginBottom:24,
        }}>
          <div style={{ fontSize:32, fontWeight:900, color:C.gold }}>+{ciclo.tl} Talentos</div>
          <div style={{ color:C.muted, fontSize:14 }}>adicionados ao seu perfil</div>
        </div>
        <button onClick={onVoltar} style={{
          width:"100%", minHeight:48, padding:"14px 0", borderRadius:12, cursor:"pointer",
          background:`linear-gradient(135deg,${C.accent},#EA580C)`,
          color:"#fff", fontWeight:600, fontSize:16, border:"none", fontFamily:"inherit", boxSizing:"border-box",
          boxShadow:`0 4px 20px ${C.accent}50`,
        }}>Voltar ao início</button>
      </div>
    </div>
  );

  return (
    <div style={{ fontFamily:"'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif", background:C.bg, minHeight:"100vh", color:C.text }}>
      {showToast && <Toast tl={ciclo.tl}/>}
      <AppHeader perfil={perfil} userTL={userTL} onHome={onVoltar}/>
      <div style={{ background:C.surface, borderBottom:`1px solid ${C.border}`, padding:"15px 20px" }}>
        <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:10 }}>
          <button onClick={onVoltar} style={{ background:"none", border:"none", color:C.muted, cursor:"pointer", fontSize:22 }}>←</button>
          <span style={{ fontWeight:700 }}>{objeto?.icon} {objeto?.nome}</span>
          <span style={{ marginLeft:"auto", color:C.muted, fontSize:14 }}>{pergAtual+1}/{perguntas.length}</span>
        </div>
        <div style={{ height:5, background:C.border, borderRadius:10, overflow:"hidden" }}>
          <div style={{
            height:"100%", borderRadius:10, transition:"width 0.4s ease",
            width:`${((pergAtual+1)/perguntas.length)*100}%`,
            background:`linear-gradient(90deg,${C.accent},${C.purple})`,
            boxShadow:`0 0 8px ${C.accent}80`,
          }}/>
        </div>
      </div>
      <div style={{ maxWidth:560, margin:"0 auto", padding:"36px 20px", boxSizing:"border-box" }}>
        <div style={{ background:C.card, borderRadius:16, padding:20, border:`1px solid ${C.border}` }}>
          <p style={{ color:C.muted, fontSize:14, letterSpacing:2, textTransform:"uppercase", margin:"0 0 10px" }}>
            Pergunta {pergAtual+1} de {perguntas.length}
          </p>
          <h3 style={{ fontSize:18, fontWeight:600, lineHeight:1.55, margin:"0 0 26px" }}>{perg.texto}</h3>
          {perg.tipo==="escala"  && <EscalaInput  value={respostas[perg.id]} onChange={v=>setRespostas(r=>({...r,[perg.id]:v}))}/>}
          {perg.tipo==="binaria" && <BinariaInput value={respostas[perg.id]} onChange={v=>setRespostas(r=>({...r,[perg.id]:v}))}/>}
          {perg.tipo==="aberta"  && (
            <textarea value={respostas[perg.id]||""} onChange={e=>setRespostas(r=>({...r,[perg.id]:e.target.value}))}
              placeholder="Escreva sua resposta (opcional)..."
              style={{
                width:"100%", minHeight:96, background:C.bg, color:C.text, fontSize:16, padding:14,
                border:`1px solid ${C.border}`, borderRadius:12, resize:"vertical",
                fontFamily:"inherit", boxSizing:"border-box",
              }}/>
          )}
        </div>
        <div style={{ display:"flex", gap:12, marginTop:16 }}>
          {pergAtual>0
            ? <button onClick={()=>setPergAtual(p=>p-1)} style={{
                flex:1, minHeight:48, padding:"13px 0", borderRadius:12, background:C.card, color:C.text,
                border:`1px solid ${C.border}`, cursor:"pointer", fontWeight:600, fontSize:16, fontFamily:"inherit", boxSizing:"border-box",
              }}>← Anterior</button>
            : <div style={{ flex:1 }}/>
          }
          <button
            disabled={enviando || !respondida(perg)}
            onClick={()=>pergAtual<perguntas.length-1?setPergAtual(p=>p+1):enviar()}
            style={{
              flex:2, minHeight:48, padding:"13px 0", borderRadius:12,
              cursor:(enviando || !respondida(perg))?"default":"pointer", fontFamily:"inherit", boxSizing:"border-box",
              background:`linear-gradient(135deg,${C.accent},#EA580C)`,
              color:"#fff", fontWeight:600, fontSize:16, border:"none",
              boxShadow:`0 4px 16px ${C.accent}40`, opacity:(enviando || !respondida(perg))?0.5:1,
            }}>
            {enviando ? "Enviando..." : pergAtual<perguntas.length-1?"Próxima →":`Enviar e ganhar +${ciclo.tl} TL ✓`}
          </button>
        </div>
        {!respondida(perg) && (
          <p style={{ color:C.muted, fontSize:14, textAlign:"center", marginTop:10 }}>
            Responda para continuar.
          </p>
        )}
      </div>
    </div>
  );
}

// ── GESTÃO DE MISSIONÁRIOS ───────────────────────────────────────────────────
function GestaoMissionarios({ perfil, userTL, onVoltar, missionarios, setMissionarios, token }) {
  const isGestor = perfil === "gestor";
  const [equipes, setEquipes]           = useState(EQUIPES_INIT);
  const [busca, setBusca]               = useState("");
  const [erroEquipes, setErroEquipes]   = useState("");
  const [filtroEquipe, setFiltroEquipe] = useState("");
  const [filtroStatus, setFiltroStatus] = useState("");
  const [modalForm, setModalForm]       = useState(null);
  const [modalMsg, setModalMsg]         = useState(null);
  const [modalAlerta, setModalAlerta]   = useState(false);
  const [modalImport, setModalImport]   = useState(false);
  const [modalEquipes, setModalEquipes] = useState(false);
  const [erroSalvar, setErroSalvar]     = useState("");
  const fileRef = useRef();

  // Equipes agora vêm da API (antes eram só um array em memória, perdido a cada reload).
  useEffect(() => {
    if (!token) return;
    (async () => {
      try {
        const dados = await api.listarEquipes(token);
        setEquipes(dados.map(e => ({ id: e.id, lider: e.nome })));
      } catch (err) {
        setErroEquipes(err.message || "Não foi possível carregar as equipes da API.");
      }
    })();
  }, [token]);

  const aniversariantes = aniversariantesHoje(missionarios);

  const lista = missionarios.filter(m => {
    const matchBusca  = m.nome.toLowerCase().includes(busca.toLowerCase()) || m.email.toLowerCase().includes(busca.toLowerCase());
    const matchEquipe = !filtroEquipe || m.equipeId === filtroEquipe;
    const matchStatus = !filtroStatus || m.status === filtroStatus;
    return matchBusca && matchEquipe && matchStatus;
  });

  async function salvar(form) {
    setErroSalvar("");
    if (!token) {
      // Sem sessão ativa (uso local/offline): mantém o comportamento antigo em memória
      if (form.id) setMissionarios(ms=>ms.map(m=>m.id===form.id?{...m,...form}:m));
      else         setMissionarios(ms=>[...ms,{...form,id:uid(),tl:0}]);
      setModalForm(null);
      return;
    }
    try {
      if (form.id) {
        const atualizado = await api.atualizarMissionario(token, form.id, form);
        setMissionarios(ms=>ms.map(m=>m.id===form.id?atualizado:m));
      } else {
        const criado = await api.criarMissionario(token, form);
        setMissionarios(ms=>[...ms, criado]);
      }
      setModalForm(null);
    } catch (err) {
      setErroSalvar(err.message || "Não foi possível salvar o missionário na API.");
    }
  }

  async function salvarEquipes() {
    if (!token) { setEquipes(listaEquipes); setModalEquipes(false); return; }
    try {
      const idsOriginais = new Set(equipes.map(e => e.id));
      const idsNovos = new Set(listaEquipes.map(e => e.id));

      for (const e of equipes.filter(e => !idsNovos.has(e.id))) {
        await api.removerEquipe(token, e.id);
      }
      for (const e of listaEquipes.filter(e => idsOriginais.has(e.id))) {
        const original = equipes.find(o => o.id === e.id);
        if (original && original.lider !== e.lider) await api.atualizarEquipe(token, e.id, e.lider);
      }
      for (const e of listaEquipes.filter(e => !idsOriginais.has(e.id))) {
        await api.criarEquipe(token, e.lider);
      }

      const dados = await api.listarEquipes(token);
      setEquipes(dados.map(e => ({ id: e.id, lider: e.nome })));
      setModalEquipes(false);
    } catch (err) {
      alert(err.message || "Não foi possível salvar as equipes na API.");
    }
  }

  async function excluir(id) {
    if (!window.confirm("Deseja remover este missionário?")) return;
    if (!token) { setMissionarios(ms=>ms.filter(m=>m.id!==id)); return; }
    try {
      await api.removerMissionario(token, id);
      setMissionarios(ms=>ms.filter(m=>m.id!==id));
    } catch (err) {
      alert(err.message || "Não foi possível remover o missionário na API.");
    }
  }

  // Parseia CSV
  function parsearCSV(texto) {
    const linhas = texto.trim().split("\n").map(l=>l.split(",").map(c=>c.trim().replace(/^"|"$/g,"")));
    const header = linhas[0].map(h=>h.toLowerCase());
    return linhas.slice(1).map(cols=>{
      const obj={};
      header.forEach((h,i)=>obj[h]=cols[i]||"");
      return obj;
    });
  }

  const [csvPreview, setCsvPreview] = useState(null);
  const [csvErro, setCsvErro]       = useState("");

  function handleArquivo(e) {
    const file = e.target.files[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const dados = parsearCSV(ev.target.result);
        const faltando = ["nome","email","whatsapp"].filter(c=>!Object.keys(dados[0]||{}).includes(c));
        if (faltando.length) { setCsvErro(`Colunas ausentes: ${faltando.join(", ")}`); return; }
        setCsvPreview(dados.slice(0,5)); setCsvErro("");
      } catch { setCsvErro("Arquivo inválido. Use CSV: nome, email, whatsapp, equipeId, nascimento, status"); }
    };
    reader.readAsText(file);
  }

  async function confirmarImport() {
    const linhas = csvPreview.map(r=>({
      nome:r.nome, email:r.email, whatsapp:r.whatsapp,
      equipeId:r.equipeid||equipes[0]?.id||"",
      nascimento:r.nascimento||"",
      status:r.status==="inativo"?"inativo":"ativo",
    }));

    if (!token) {
      setMissionarios(ms=>[...ms, ...linhas.map(r=>({...r, id:uid(), tl:0}))]);
      setCsvPreview(null); setModalImport(false);
      return;
    }

    const criados = [];
    const falhas = [];
    for (const linha of linhas) {
      try { criados.push(await api.criarMissionario(token, linha)); }
      catch { falhas.push(linha.nome); }
    }
    if (criados.length) setMissionarios(ms=>[...ms, ...criados]);
    if (falhas.length) alert(`Não foi possível importar: ${falhas.join(", ")}`);
    setCsvPreview(null); setModalImport(false);
  }

  // Estados para alerta em massa
  const WA_GRUPO_DEFAULT = "https://chat.whatsapp.com/SEU_LINK_DO_GRUPO";
  const [alertaCanal, setAlertaCanal]       = useState("wa_grupo");
  const [alertaAssunto, setAlertaAssunto]   = useState("Aviso da SEPAL");
  const [alertaMsg, setAlertaMsg]           = useState("");
  const [alertaIdx, setAlertaIdx]           = useState(null);
  const [grupoWALink, setGrupoWALink]       = useState(WA_GRUPO_DEFAULT);
  const ativos = missionarios.filter(m=>m.status==="ativo");

  function iniciarAlerta() {
    if (alertaCanal === "wa_grupo") {
      const urlGrupo = grupoWALink + (alertaMsg ? `?text=${encodeURIComponent(alertaMsg)}` : "");
      window.open(urlGrupo, "_blank");
      setAlertaIdx("fim");
    } else {
      setAlertaIdx(0);
    }
  }

  function abrirProximoAlerta() {
    const m = ativos[alertaIdx];
    const url = alertaCanal === "wa_individual"
      ? linkWA(m.whatsapp, alertaMsg)
      : linkEmail(m.email, alertaAssunto, alertaMsg);
    window.open(url, "_blank");
    setAlertaIdx(idx => idx + 1 < ativos.length ? idx + 1 : "fim");
  }

  // Form missionário
  const MISS_VAZIO = { nome:"", email:"", whatsapp:"", equipeId:"", nascimento:"", status:"ativo" };
  const [formData, setFormData] = useState(MISS_VAZIO);
  const setF = (k,v) => setFormData(f=>({...f,[k]:v}));

  function abrirForm(m) {
    setFormData(m && m !== "novo" ? {...m} : MISS_VAZIO);
    setErroSalvar("");
    setModalForm(m || "novo");
  }

  // Msg individual
  const [msgCanal, setMsgCanal]     = useState("whatsapp");
  const [msgAssunto, setMsgAssunto] = useState("Mensagem da SEPAL");
  const [msgTexto, setMsgTexto]     = useState("");

  function enviarMsg() {
    const url = msgCanal==="whatsapp"
      ? linkWA(modalMsg.whatsapp, msgTexto)
      : linkEmail(modalMsg.email, msgAssunto, msgTexto);
    window.open(url,"_blank");
    setModalMsg(null); setMsgTexto("");
  }

  // Equipes
  const [listaEquipes, setListaEquipes] = useState(equipes);
  const [novoLider, setNovoLider]       = useState("");

  return (
    <div style={{ fontFamily:"'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif", background:C.bg, minHeight:"100vh", color:C.text }}>
      <AppHeader perfil={perfil} userTL={userTL} onHome={onVoltar}/>

      {/* Sub-header */}
      <div style={{ background:C.surface, borderBottom:`1px solid ${C.border}`, padding:"13px 20px", display:"flex", alignItems:"center", gap:10 }}>
        <button onClick={onVoltar} style={{ background:"none", border:"none", color:C.muted, cursor:"pointer", fontSize:20 }}>←</button>
        <span style={{ fontWeight:700, fontSize:16 }}>👥 Gestão de Missionários</span>
        <span style={{ color:C.muted, fontSize:14 }}>· {missionarios.length} cadastrados</span>
      </div>

      <div style={{ maxWidth:1000, margin:"0 auto", padding:"24px 20px", boxSizing:"border-box" }}>

        {erroEquipes && (
          <div style={{
            background:`${C.danger}18`, border:`1px solid ${C.danger}50`, borderRadius:12,
            color:C.danger, fontSize:14, padding:"10px 16px", marginBottom:16,
          }}>⚠ {erroEquipes}</div>
        )}

        {/* Banner aniversariantes */}
        {aniversariantes.length>0 && (
          <div style={{
            background:`linear-gradient(135deg,${C.gold}20,${C.accent}10)`,
            border:`1px solid ${C.gold}40`, borderRadius:14, padding:"14px 18px",
            marginBottom:20, display:"flex", alignItems:"center", gap:14, flexWrap:"wrap",
          }}>
            <span style={{ fontSize:28 }}>🎂</span>
            <div style={{ flex:1 }}>
              <div style={{ fontWeight:700, fontSize:16, color:C.gold }}>
                {aniversariantes.length===1
                  ? `Hoje é aniversário de ${aniversariantes[0].nome}!`
                  : `${aniversariantes.length} aniversariantes hoje!`}
              </div>
              <div style={{ color:C.muted, fontSize:14 }}>Envie uma mensagem de celebração</div>
            </div>
            {aniversariantes.map(m=>(
              <div key={m.id} style={{ display:"flex", gap:6 }}>
                <Btn small color={C.success} onClick={()=>window.open(linkWA(m.whatsapp,`Parabéns, ${m.nome.split(" ")[0]}! 🎉 A SEPAL celebra com você!`),"_blank")}>💬 WA</Btn>
                <Btn small color={C.accent} outline onClick={()=>window.open(linkEmail(m.email,`Feliz Aniversário, ${m.nome.split(" ")[0]}! 🎉`,`Olá ${m.nome.split(" ")[0]},\n\nA SEPAL celebra com você neste dia especial!\n\nCom carinho,\nEquipe SEPAL`),"_blank")}>📧 Email</Btn>
              </div>
            ))}
          </div>
        )}

        {/* Ações */}
        {isGestor && (
          <div style={{ display:"flex", gap:10, flexWrap:"wrap", marginBottom:20 }}>
            <Btn onClick={()=>abrirForm("novo")}>+ Novo missionário</Btn>
            <Btn outline color={C.accent} onClick={()=>{setCsvPreview(null);setCsvErro("");setModalImport(true);}}>📥 Importar Excel</Btn>
            <Btn outline color={C.purple} onClick={()=>{setListaEquipes(equipes);setModalEquipes(true);}}>👥 Gerenciar equipes</Btn>
            <Btn outline color={C.warning} onClick={()=>{setAlertaIdx(null);setAlertaMsg("");setModalAlerta(true);}}>📣 Alerta para todos</Btn>
          </div>
        )}

        {/* Filtros */}
        <div style={{ display:"flex", gap:10, marginBottom:20, flexWrap:"wrap" }}>
          <input value={busca} onChange={e=>setBusca(e.target.value)} placeholder="🔍 Buscar por nome ou e-mail..."
            style={{ flex:2, minWidth:200, height:48, padding:"0 14px", borderRadius:12, fontSize:16, background:C.card, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", boxSizing:"border-box" }}/>
          <select value={filtroEquipe} onChange={e=>setFiltroEquipe(e.target.value)} style={{ flex:1, minWidth:150, height:48, padding:"0 14px", borderRadius:12, fontSize:16, background:C.card, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", boxSizing:"border-box" }}>
            <option value="">Todas as equipes</option>
            {equipes.map(e=><option key={e.id} value={e.id}>Equipe de {e.lider}</option>)}
          </select>
          <select value={filtroStatus} onChange={e=>setFiltroStatus(e.target.value)} style={{ flex:1, minWidth:120, height:48, padding:"0 14px", borderRadius:12, fontSize:16, background:C.card, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", boxSizing:"border-box" }}>
            <option value="">Todos</option>
            <option value="ativo">Ativos</option>
            <option value="inativo">Inativos</option>
          </select>
        </div>

        {/* Stats */}
        <div style={{ display:"flex", gap:10, marginBottom:20 }}>
          {[["Total",missionarios.length,C.text],["Ativos",missionarios.filter(m=>m.status==="ativo").length,C.success],["Equipes",equipes.length,C.purple]].map(([label,val,cor])=>(
            <div key={label} style={{ background:C.card, borderRadius:12, padding:"12px 18px", border:`1px solid ${C.border}`, textAlign:"center", minWidth:80 }}>
              <div style={{ fontSize:22, fontWeight:900, color:cor }}>{val}</div>
              <div style={{ color:C.muted, fontSize:14 }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Tabela */}
        <div style={{ background:C.card, borderRadius:16, border:`1px solid ${C.border}`, overflow:"hidden" }}>
          <div style={{
            display:"grid", gridTemplateColumns:"2fr 2fr 1.5fr 1fr 1fr auto",
            padding:"12px 18px", borderBottom:`1px solid ${C.border}`,
            color:C.muted, fontSize:14, letterSpacing:1, textTransform:"uppercase",
          }}>
            <span>Nome</span><span>Contato</span><span>Equipe</span><span>Nascimento</span><span>Status</span><span>Ações</span>
          </div>

          {lista.length===0 && <div style={{ padding:40, textAlign:"center", color:C.muted }}>Nenhum missionário encontrado</div>}

          {lista.map((m,i)=>{
            const eq = equipes.find(e=>e.id===m.equipeId);
            return (
              <div key={m.id} style={{
                display:"grid", gridTemplateColumns:"2fr 2fr 1.5fr 1fr 1fr auto",
                padding:"14px 18px", alignItems:"center",
                borderBottom:i<lista.length-1?`1px solid ${C.border}`:"none",
                transition:"background 0.15s",
              }}
                onMouseEnter={e=>e.currentTarget.style.background=C.surface}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}
              >
                <div>
                  <div style={{ fontWeight:700, fontSize:14 }}>{m.nome}</div>
                  <div style={{ color:C.muted, fontSize:14, marginTop:2 }}>{m.tl} TL</div>
                </div>
                <div>
                  <div style={{ fontSize:14, color:C.muted }}>{m.email}</div>
                  <div style={{ fontSize:14, color:C.muted }}>{m.whatsapp}</div>
                </div>
                <div style={{ fontSize:14 }}>{eq?`Eq. ${eq.lider.split(" ")[0]}`:"—"}</div>
                <div style={{ fontSize:14, color:C.muted }}>{fmtData(m.nascimento)}</div>
                <div><Badge color={m.status==="ativo"?C.success:C.muted}>{m.status==="ativo"?"Ativo":"Inativo"}</Badge></div>
                <div style={{ display:"flex", gap:5 }}>
                  <button title="Mensagem" onClick={()=>{setMsgCanal("whatsapp");setMsgTexto("");setModalMsg(m);}} style={{ background:C.success+"22", border:`1px solid ${C.success}44`, color:C.success, borderRadius:8, padding:"6px 9px", cursor:"pointer", fontSize:14 }}>💬</button>
                  <button title="Editar" onClick={()=>abrirForm(m)} style={{ background:C.accent+"22", border:`1px solid ${C.accent}44`, color:C.accent, borderRadius:8, padding:"6px 9px", cursor:"pointer", fontSize:14 }}>✏️</button>
                  {isGestor && <button title="Remover" onClick={()=>excluir(m.id)} style={{ background:C.danger+"22", border:`1px solid ${C.danger}44`, color:C.danger, borderRadius:8, padding:"6px 9px", cursor:"pointer", fontSize:14 }}>🗑</button>}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* MODAL: Form missionário */}
      {modalForm && (
        <Modal titulo={modalForm==="novo"?"Novo missionário":isGestor?`Editar — ${formData.nome}`:"Meu perfil"} onClose={()=>setModalForm(null)}>
          {!isGestor && <p style={{ color:C.muted, fontSize:14, marginBottom:16 }}>Você pode editar apenas sua data de nascimento.</p>}
          {isGestor && <>
            <FieldInput label="Nome completo *" value={formData.nome} onChange={e=>setF("nome",e.target.value)}/>
            <FieldInput label="E-mail *" type="email" value={formData.email} onChange={e=>setF("email",e.target.value)}/>
            <FieldInput label="WhatsApp * (com DDD e código do país)" value={formData.whatsapp} placeholder="5511999990000" onChange={e=>setF("whatsapp",e.target.value)}/>
            <FieldSelect label="Equipe *" value={formData.equipeId} onChange={e=>setF("equipeId",e.target.value)}
              options={equipes.map(e=>({value:e.id,label:`Equipe de ${e.lider}`}))}/>
            <FieldSelect label="Status" value={formData.status} onChange={e=>setF("status",e.target.value)}
              options={[{value:"ativo",label:"Ativo"},{value:"inativo",label:"Inativo"}]}/>
          </>}
          <FieldInput label="Data de nascimento" type="date" value={formData.nascimento} onChange={e=>setF("nascimento",e.target.value)}/>
          {erroSalvar && <p style={{ color:C.danger, fontSize:14, margin:"0 0 8px" }}>⚠ {erroSalvar}</p>}
          <div style={{ display:"flex", gap:10, justifyContent:"flex-end", marginTop:8 }}>
            <Btn outline color={C.muted} onClick={()=>setModalForm(null)}>Cancelar</Btn>
            <Btn onClick={()=>salvar(formData)} disabled={isGestor&&(!formData.nome||!formData.email||!formData.whatsapp||!formData.equipeId)}>Salvar</Btn>
          </div>
        </Modal>
      )}

      {/* MODAL: Mensagem individual */}
      {modalMsg && (
        <Modal titulo={`Mensagem para ${modalMsg.nome}`} onClose={()=>setModalMsg(null)}>
          <div style={{ display:"flex", gap:8, marginBottom:16 }}>
            {[["whatsapp","💬 WhatsApp",C.success],["email","📧 E-mail",C.accent]].map(([id,label,cor])=>(
              <button key={id} onClick={()=>setMsgCanal(id)} style={{
                flex:1, minHeight:48, padding:"10px 0", borderRadius:12, cursor:"pointer", fontWeight:600, fontSize:16, boxSizing:"border-box",
                border:`2px solid ${msgCanal===id?cor:C.border}`,
                background:msgCanal===id?cor+"22":C.card, color:msgCanal===id?cor:C.muted, fontFamily:"inherit",
              }}>{label}</button>
            ))}
          </div>
          {msgCanal==="email" && <FieldInput label="Assunto" value={msgAssunto} onChange={e=>setMsgAssunto(e.target.value)}/>}
          <div style={{ marginBottom:14 }}>
            <label style={{ display:"block", color:C.muted, fontSize:14, marginBottom:5 }}>Mensagem</label>
            <textarea value={msgTexto} onChange={e=>setMsgTexto(e.target.value)}
              placeholder={msgCanal==="whatsapp"?"Olá! Aqui é a equipe da SEPAL...":"Escreva sua mensagem..."}
              style={{ width:"100%", minHeight:100, padding:14, borderRadius:12, fontSize:16, background:C.surface, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", resize:"vertical", boxSizing:"border-box" }}/>
          </div>
          <div style={{ display:"flex", gap:10, justifyContent:"flex-end" }}>
            <Btn outline color={C.muted} onClick={()=>setModalMsg(null)}>Cancelar</Btn>
            <Btn color={msgCanal==="whatsapp"?C.success:C.accent} onClick={enviarMsg} disabled={!msgTexto}>
              {msgCanal==="whatsapp"?"Abrir WhatsApp →":"Abrir E-mail →"}
            </Btn>
          </div>
        </Modal>
      )}

      {/* MODAL: Alerta em massa */}
      {modalAlerta && (
        <Modal titulo="📣 Alerta para todos os missionários" onClose={()=>setModalAlerta(false)}>
          {alertaIdx===null && <>
            {/* Stats */}
            <div style={{ background:C.card, borderRadius:16, padding:20, marginBottom:16, border:`1px solid ${C.border}`, display:"flex", gap:16 }}>
              <div><div style={{ fontSize:14, color:C.muted }}>Missionários ativos</div><div style={{ fontSize:22, fontWeight:800 }}>{ativos.length}</div></div>
            </div>

            {/* Seleção de canal */}
            <label style={{ display:"block", color:C.muted, fontSize:14, marginBottom:8 }}>Canal de envio</label>
            <div style={{ display:"flex", gap:8, marginBottom:16 }}>
              {[
                ["wa_grupo",     "💬 Grupo WA",     C.success, "Padrão — 1 clique"],
                ["email",        "📧 E-mail",        C.accent,  "Individual por e-mail"],
                ["wa_individual","📱 WA Individual", C.purple,  "1 a 1 no WhatsApp"],
              ].map(([id,label,cor,sub])=>(
                <button key={id} onClick={()=>setAlertaCanal(id)} style={{
                  flex:1, minHeight:48, padding:"10px 8px", borderRadius:12, cursor:"pointer", fontFamily:"inherit", boxSizing:"border-box",
                  border:`2px solid ${alertaCanal===id?cor:C.border}`,
                  background:alertaCanal===id?cor+"22":C.card,
                  color:alertaCanal===id?cor:C.muted,
                  textAlign:"center",
                }}>
                  <div style={{ fontWeight:700, fontSize:14 }}>{label}</div>
                  <div style={{ fontSize:14, opacity:0.75, marginTop:2 }}>{sub}</div>
                </button>
              ))}
            </div>

            {/* Link do grupo WA — só no modo grupo */}
            {alertaCanal==="wa_grupo" && (
              <FieldInput
                label="Link do grupo do WhatsApp"
                value={grupoWALink}
                onChange={e=>setGrupoWALink(e.target.value)}
                placeholder="https://chat.whatsapp.com/..."
              />
            )}

            {/* Assunto — só email */}
            {alertaCanal==="email" && (
              <FieldInput label="Assunto do e-mail" value={alertaAssunto} onChange={e=>setAlertaAssunto(e.target.value)}/>
            )}

            {/* Mensagem */}
            <div style={{ marginBottom:12 }}>
              <label style={{ display:"block", color:C.muted, fontSize:14, marginBottom:5 }}>
                Mensagem {alertaCanal==="wa_grupo" && <span style={{ color:C.muted, fontWeight:400 }}>(será pré-preenchida no grupo)</span>}
              </label>
              <textarea value={alertaMsg} onChange={e=>setAlertaMsg(e.target.value)} placeholder="Escreva o alerta..."
                style={{ width:"100%", minHeight:96, padding:14, borderRadius:12, fontSize:16, background:C.surface, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", resize:"vertical", boxSizing:"border-box" }}/>
            </div>

            {/* Nota de comportamento */}
            <div style={{ background:C.card, borderRadius:10, padding:"10px 14px", marginBottom:16, border:`1px solid ${C.border}` }}>
              {alertaCanal==="wa_grupo"     && <span style={{ color:C.muted, fontSize:14 }}>💬 Abrirá o grupo do WhatsApp com a mensagem pré-preenchida. Você confirma o envio no WhatsApp.</span>}
              {alertaCanal==="email"        && <span style={{ color:C.muted, fontSize:14 }}>📧 Abrirá seu cliente de e-mail individualmente para cada um dos {ativos.length} missionários ativos.</span>}
              {alertaCanal==="wa_individual"&& <span style={{ color:C.muted, fontSize:14 }}>📱 Abrirá o WhatsApp individualmente para cada um dos {ativos.length} missionários. Você confirma cada envio.</span>}
            </div>

            <div style={{ display:"flex", gap:10, justifyContent:"flex-end" }}>
              <Btn outline color={C.muted} onClick={()=>setModalAlerta(false)}>Cancelar</Btn>
              <Btn
                color={alertaCanal==="wa_grupo"?C.success:alertaCanal==="email"?C.accent:C.purple}
                onClick={iniciarAlerta}
                disabled={!alertaMsg||(alertaCanal==="wa_grupo"&&!grupoWALink)}
              >
                {alertaCanal==="wa_grupo"?"Abrir grupo →":alertaCanal==="email"?`Enviar para ${ativos.length} e-mails →`:`Enviar para ${ativos.length} WAs →`}
              </Btn>
            </div>
          </>}

          {/* Progresso individual (email ou wa_individual) */}
          {typeof alertaIdx==="number" && alertaIdx!=="fim" && (
            <div style={{ textAlign:"center" }}>
              <div style={{ fontSize:48, marginBottom:12 }}>{alertaCanal==="wa_individual"?"📱":"📧"}</div>
              <div style={{ color:C.muted, fontSize:14, marginBottom:4 }}>{alertaIdx+1} de {ativos.length}</div>
              <div style={{ fontWeight:700, fontSize:18, marginBottom:6 }}>{ativos[alertaIdx].nome}</div>
              <div style={{ color:C.muted, fontSize:14, marginBottom:20 }}>
                {alertaCanal==="wa_individual" ? ativos[alertaIdx].whatsapp : ativos[alertaIdx].email}
              </div>
              <div style={{ height:6, background:C.border, borderRadius:10, marginBottom:24, overflow:"hidden" }}>
                <div style={{ height:"100%", background:alertaCanal==="wa_individual"?C.purple:C.accent, borderRadius:10, width:`${(alertaIdx/ativos.length)*100}%`, transition:"width 0.3s" }}/>
              </div>
              <Btn
                color={alertaCanal==="wa_individual"?C.purple:C.accent}
                onClick={abrirProximoAlerta}
              >
                {alertaCanal==="wa_individual"?"Abrir WhatsApp →":"Abrir E-mail →"}
              </Btn>
            </div>
          )}

          {alertaIdx==="fim" && (
            <div style={{ textAlign:"center" }}>
              <div style={{ fontSize:48, marginBottom:12 }}>✅</div>
              <div style={{ fontWeight:700, fontSize:18, marginBottom:8 }}>
                {alertaCanal==="wa_grupo" ? "Grupo aberto!" : "Envio concluído!"}
              </div>
              <div style={{ color:C.muted, fontSize:14, marginBottom:20 }}>
                {alertaCanal==="wa_grupo"
                  ? "A mensagem foi pré-preenchida no grupo do WhatsApp."
                  : `${ativos.length} mensagens enviadas`}
              </div>
              <Btn onClick={()=>{setModalAlerta(false);setAlertaIdx(null);}}>Fechar</Btn>
            </div>
          )}
        </Modal>
      )}

      {/* MODAL: Importar CSV */}
      {modalImport && (
        <Modal titulo="📥 Importar via Excel / CSV" onClose={()=>setModalImport(false)}>
          <div style={{ background:C.card, borderRadius:16, padding:20, marginBottom:16, border:`1px dashed ${C.border}` }}>
            <p style={{ color:C.muted, fontSize:14, margin:"0 0 8px" }}>Exporte sua planilha como <strong style={{ color:C.text }}>.CSV</strong> e selecione abaixo.</p>
            <p style={{ color:C.muted, fontSize:14, margin:0 }}>Colunas: <code style={{ color:C.accent }}>nome, email, whatsapp, equipeId, nascimento, status</code></p>
          </div>
          <button onClick={()=>fileRef.current.click()} style={{
            width:"100%", minHeight:48, padding:"14px 0", borderRadius:12, cursor:"pointer",
            background:C.card, border:`1px solid ${C.border}`, color:C.text,
            fontFamily:"inherit", fontWeight:600, fontSize:16, marginBottom:14, boxSizing:"border-box",
          }}>📂 Selecionar arquivo CSV</button>
          <input ref={fileRef} type="file" accept=".csv" style={{ display:"none" }} onChange={handleArquivo}/>
          {csvErro && <div style={{ color:C.danger, fontSize:14, marginBottom:12 }}>⚠️ {csvErro}</div>}
          {csvPreview && <>
            <div style={{ color:C.success, fontSize:14, marginBottom:10 }}>✅ {csvPreview.length} registros encontrados (prévia)</div>
            <div style={{ overflow:"auto", marginBottom:16 }}>
              <table style={{ width:"100%", borderCollapse:"collapse", fontSize:14 }}>
                <thead><tr>{["Nome","E-mail","Status"].map(h=>(
                  <th key={h} style={{ padding:"6px 10px", textAlign:"left", color:C.muted, borderBottom:`1px solid ${C.border}` }}>{h}</th>
                ))}</tr></thead>
                <tbody>{csvPreview.map((r,i)=>(
                  <tr key={i}>
                    <td style={{ padding:"6px 10px", color:C.text }}>{r.nome}</td>
                    <td style={{ padding:"6px 10px", color:C.muted }}>{r.email}</td>
                    <td style={{ padding:"6px 10px" }}><Badge color={r.status==="inativo"?C.muted:C.success}>{r.status||"ativo"}</Badge></td>
                  </tr>
                ))}</tbody>
              </table>
            </div>
            <div style={{ display:"flex", gap:10, justifyContent:"flex-end" }}>
              <Btn outline color={C.muted} onClick={()=>setModalImport(false)}>Cancelar</Btn>
              <Btn onClick={confirmarImport}>Importar {csvPreview.length} registros</Btn>
            </div>
          </>}
        </Modal>
      )}

      {/* MODAL: Equipes */}
      {modalEquipes && (
        <Modal titulo="👥 Gestão de Equipes" onClose={()=>setModalEquipes(false)}>
          <p style={{ color:C.muted, fontSize:14, margin:"0 0 16px" }}>Equipes são identificadas pelo nome do(a) líder. Edite diretamente.</p>
          <div style={{ marginBottom:16 }}>
            {listaEquipes.map(e=>(
              <div key={e.id} style={{ display:"flex", gap:8, alignItems:"center", marginBottom:8 }}>
                <span style={{ fontSize:18 }}>👤</span>
                <input value={e.lider} onChange={ev=>setListaEquipes(l=>l.map(x=>x.id===e.id?{...x,lider:ev.target.value}:x))}
                  style={{ flex:1, height:48, padding:"0 12px", borderRadius:12, fontSize:16, background:C.surface, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", boxSizing:"border-box" }}/>
                <button onClick={()=>setListaEquipes(l=>l.filter(x=>x.id!==e.id))} style={{ background:"none", border:"none", color:C.danger, cursor:"pointer", fontSize:18 }}>×</button>
              </div>
            ))}
          </div>
          <div style={{ display:"flex", gap:8, marginBottom:20 }}>
            <input value={novoLider} onChange={e=>setNovoLider(e.target.value)} placeholder="Nome do(a) novo(a) líder..."
              style={{ flex:1, height:48, padding:"0 12px", borderRadius:12, fontSize:16, background:C.surface, border:`1px solid ${C.border}`, color:C.text, fontFamily:"inherit", boxSizing:"border-box" }}/>
            <Btn onClick={()=>{ if(novoLider.trim()){setListaEquipes(l=>[...l,{id:"e"+Date.now(),lider:novoLider.trim()}]);setNovoLider("");}}} disabled={!novoLider.trim()}>+ Adicionar</Btn>
          </div>
          <div style={{ display:"flex", gap:10, justifyContent:"flex-end" }}>
            <Btn outline color={C.muted} onClick={()=>setModalEquipes(false)}>Cancelar</Btn>
            <Btn onClick={salvarEquipes}>Salvar equipes</Btn>
          </div>
        </Modal>
      )}
    </div>
  );
}

// ── ROOT ─────────────────────────────────────────────────────────────────────
export default function App() {
  const [tela, setTela]             = useState("login");
  const [perfil, setPerfil]         = useState(null);
  const [usuario, setUsuario]       = useState(null);
  const [token, setToken]           = useState(null);
  const [cicloAtivo, setCicloAtivo] = useState(null);
  const [userTL, setUserTL]         = useState(0);
  const [missionarios, setMissionarios] = useState(MISSIONARIOS_INIT);
  const [dadosFinanceiros, setDadosFinanceiros] = useState([]);
  const [kpisApi, setKpisApi]       = useState(null);
  const [erroApi, setErroApi]       = useState("");
  // Histórico real do usuário logado, vindo da API — base para os Talentos exibidos e as Conquistas.
  const [meuHistorico, setMeuHistorico] = useState({ missionarioId: null, ciclosCompletos: 0, tiposFeitos: [], criadoEm: null });

  // Retoma a sessão salva (se o usuário já tinha feito login antes)
  useEffect(() => {
    const sessao = carregarSessao();
    if (sessao) {
      setToken(sessao.token);
      setUsuario(sessao.usuario);
      setPerfil(sessao.usuario.papel);
      setTela("dashboard");
    }
  }, []);

  // Sempre que houver um token válido, busca missionários e KPIs reais da API
  useEffect(() => {
    if (!token) return;
    (async () => {
      try {
        const [listaMissionarios, kpis] = await Promise.all([
          api.listarMissionarios(token),
          api.buscarKpis(token),
        ]);
        setMissionarios(listaMissionarios);
        setKpisApi(kpis);
        setErroApi("");

        const meu = listaMissionarios.find(m =>
          m.email && usuario?.email && m.email.toLowerCase() === usuario.email.toLowerCase()
        );
        if (meu) {
          setUserTL(meu.tl || 0);
          try {
            const pulsos = await api.listarPulsosMissionario(token, meu.id);
            const submissoes = new Set(pulsos.map(p => p.submissao_id));
            const tipos = [...new Set(pulsos.map(p => p.ciclo))];
            setMeuHistorico({ missionarioId: meu.id, ciclosCompletos: submissoes.size, tiposFeitos: tipos, criadoEm: meu.criado_em });
          } catch {
            setMeuHistorico({ missionarioId: meu.id, ciclosCompletos: 0, tiposFeitos: [], criadoEm: meu.criado_em });
          }
        }
      } catch (err) {
        setErroApi(err.message || "Não foi possível carregar dados da API.");
      }
    })();
  }, [token, usuario]);

  const minhaPosicaoRanking = kpisApi?.rankingTalentos?.find(r => r.eu)?.pos ?? null;
  const conquistas = calcularConquistas({
    tl: userTL,
    ciclosCompletos: meuHistorico.ciclosCompletos,
    tiposFeitos: meuHistorico.tiposFeitos,
    posicaoRanking: minhaPosicaoRanking,
    criadoEm: meuHistorico.criadoEm,
  });

  function entrar(usuarioLogado, tokenNovo) {
    salvarSessao(tokenNovo, usuarioLogado);
    setUsuario(usuarioLogado);
    setToken(tokenNovo);
    setPerfil(usuarioLogado.papel);
    setTela("dashboard");
  }

  function sair() {
    limparSessao();
    setUsuario(null);
    setToken(null);
    setPerfil(null);
    setKpisApi(null);
    setUserTL(0);
    setMeuHistorico({ missionarioId: null, ciclosCompletos: 0, tiposFeitos: [], criadoEm: null });
    setTela("login");
  }

  if (tela==="login")
    return <Login onLogin={entrar}/>;

  if (tela==="dashboard")
    return <Dashboard
      perfil={perfil} userTL={userTL}
      ciclosCompletos={meuHistorico.ciclosCompletos}
      posicaoRanking={minhaPosicaoRanking}
      conquistas={conquistas}
      missionarios={missionarios}
      dadosFinanceiros={dadosFinanceiros}
      kpisApi={kpisApi}
      erroApi={erroApi}
      onSair={sair}
      onAvaliar={ciclo=>{ setCicloAtivo(ciclo); setTela("avaliar"); }}
      onMissionarios={()=>setTela("missionarios")}
    />;

  if (tela==="avaliar")
    return <Avaliacao
      cicloId={cicloAtivo} perfil={perfil} userTL={userTL}
      token={token} usuario={usuario} missionarios={missionarios}
      onVoltar={()=>setTela("dashboard")}
      onConcluir={(novoTotalTalentos)=>{ setUserTL(novoTotalTalentos); setTela("dashboard"); }}
    />;

  if (tela==="missionarios")
    return <GestaoMissionarios
      perfil={perfil} userTL={userTL}
      missionarios={missionarios}
      setMissionarios={setMissionarios}
      token={token}
      onVoltar={()=>setTela("dashboard")}
    />;
}
